const { S3Client, PutObjectCommand } = require("@aws-sdk/client-s3");
const { getSignedUrl } = require("@aws-sdk/s3-request-presigner");

const s3Client = new S3Client({ region: process.env.AWS_REGION || "eu-north-1" });
const BUCKET_NAME = process.env.BUCKET_NAME || "YOUR-BUCKET-NAME"; // Replace with your actual S3 bucket name

exports.handler = async (event) => {
    // 1. Dynamically capture the origin from the incoming request (e.g., http://localhost:3000)
    const requestOrigin = event.headers?.origin || event.headers?.Origin || "*";

    // 2. Build CORS headers matching origin: true, credentials: true
    const corsHeaders = {
        "Access-Control-Allow-Origin": requestOrigin,
        "Access-Control-Allow-Credentials": "true",
        "Access-Control-Allow-Headers": "Content-Type,Authorization",
        "Access-Control-Allow-Methods": "OPTIONS,POST,GET"
    };

    // 3. Handle browser preflight OPTIONS request
    const method = event.requestContext?.http?.method || event.httpMethod;
    if (method === 'OPTIONS') {
        return {
            statusCode: 200,
            headers: corsHeaders,
            body: ""
        };
    }

    try {
        // 4. Parse incoming request body from React
        const body = event.body ? JSON.parse(event.body) : {};
        const fileName = body.fileName || "uploaded-file";
        const fileType = body.fileType || "application/octet-stream";

        const key = `uploads/${Date.now()}-${fileName}`;

        const command = new PutObjectCommand({
            Bucket: BUCKET_NAME,
            Key: key,
            ContentType: fileType,
        });

        const uploadUrl = await getSignedUrl(s3Client, command, { expiresIn: 300 });

        return {
            statusCode: 200,
            headers: corsHeaders,
            body: JSON.stringify({
                uploadUrl: uploadUrl,
                fileKey: key
            }),
        };

    } catch (error) {
        console.error("Lambda Error:", error);
        return {
            statusCode: 500,
            headers: corsHeaders,
            body: JSON.stringify({ error: error.message }),
        };
    }
};
